// Parse callback data
const callback = $input.item.json.callback_query;
const data = callback.data;
const chatId = callback.message.chat.id;
const messageId = callback.message.message_id;
const userId = callback.from.id;
const username = callback.from.username;

const parts = data.split('_');
const action = parts[0];
const subAction = parts[1] || '';
const params = parts.slice(2).join('_');

return {
  json: {
    action,
    subAction,
    params,
    fullAction: data,
    chatId,
    messageId,
    userId,
    username,
    originalMessage: callback.message,
    callbackQueryId: callback.id
  }
};

// Handle confirm_yes - save candidate
const input = $input.item.json;
const chatId = input.chatId;
const userId = input.userId;

// Get state from Redis will be done in next node
return {
  json: {
    ...input,
    stateKey: `hr_bot:state:${chatId}:${userId}`,
    confirmAction: input.subAction // 'yes', 'no', 'edit', 'cancel'
  }
};

// Prepare data for insert
const stateData = $input.item.json;
const confirmData = $('Prepare Confirm').item.json;

let state;
try {
  state = typeof stateData === 'string' ? JSON.parse(stateData) : stateData;
} catch(e) {
  state = { collectedData: {} };
}

const data = state.collectedData || {};

return {
  json: {
    full_name: data.full_name,
    age: data.age || null,
    gender: data.gender || null,
    position: data.position,
    experience: data.experience || null,
    phone: data.phone,
    phone_normalized: (data.phone || '').replace(/[^0-9]/g, '').replace(/^8/, '7'),
    object_location: data.object_location,
    status: 'направлен',
    telegram_user_id: confirmData.userId,
    telegram_username: confirmData.username,
    telegram_chat_id: confirmData.chatId,
    telegram_message_id: confirmData.messageId,
    chatId: confirmData.chatId,
    messageId: confirmData.messageId,
    stateKey: confirmData.stateKey
  }
};

