// Classify text message
const message = $input.item.json.message;
const text = message.text || '';
const chatId = message.chat.id;

const CHAT_CANDIDATES = parseInt($env.TELEGRAM_CHAT_CANDIDATES);
const CHAT_PAYMENTS = parseInt($env.TELEGRAM_CHAT_PAYMENTS);

// Эвристики
let candidateScore = 0;
let paymentScore = 0;

if (chatId === CHAT_CANDIDATES) candidateScore += 30;
else if (chatId === CHAT_PAYMENTS) paymentScore += 30;

// Телефон
if (/(\+7|8|7)[\s\-]?\(?\d{3}\)?[\s\-]?\d{3}[\s\-]?\d{2}[\s\-]?\d{2}/.test(text)) candidateScore += 30;

// Возраст
if (/\d{1,2}\s*(лет|год|года)/i.test(text)) candidateScore += 20;

// Дата в начале
if (/^\d{1,2}\.\d{1,2}/.test(text.trim())) paymentScore += 40;

// Часы
if (/\d+\s*(час|ч\.|ч\b)/i.test(text)) paymentScore += 30;

// Структура ФИО+число
const lines = text.split('\n');
if (lines.filter(l => /^[А-Яа-яЁё]+\s+[А-Яа-яЁё]*\s*\d+$/.test(l.trim())).length >= 1) paymentScore += 25;

let messageType = 'chat';
if (candidateScore > paymentScore && candidateScore >= 40) messageType = 'candidate';
else if (paymentScore > candidateScore && paymentScore >= 40) messageType = 'payment';
else if (candidateScore >= 30 || paymentScore >= 30) messageType = 'uncertain';

return {
  json: {
    message,
    messageType,
    candidateScore,
    paymentScore,
    chatId,
    userId: message.from.id,
    username: message.from.username,
    stateKey: `hr_bot:state:${chatId}:${message.from.id}`
  }
};

// Determine final message type considering Redis state
const redisData = $input.item.json;
const classifyData = $('Classify Message').item.json;

let hasState = false;
let state = null;

try {
  if (redisData && typeof redisData === 'object' && Object.keys(redisData).length > 0) {
    state = redisData;
    hasState = true;
  } else if (typeof redisData === 'string' && redisData.length > 2) {
    state = JSON.parse(redisData);
    hasState = true;
  }
} catch(e) {}

let finalType = classifyData.messageType;
if (hasState && state.step) {
  finalType = 'continuation';
}

return {
  json: {
    ...classifyData,
    finalType,
    hasState,
    state: state || { collectedData: {}, step: 'initial' }
  }
};

// Regex-based candidate parser - надёжнее LLM
const input = $input.item.json;
const text = input.message.text || '';
const existingData = input.state?.collectedData || {};

// Словари для распознавания
const POSITIONS = ['охранник', 'горничная', 'уборщица', 'уборщик', 'администратор', 'менеджер', 'повар', 'официант', 'кассир', 'продавец', 'водитель', 'грузчик', 'разнорабочий', 'техник', 'электрик', 'сантехник', 'слесарь', 'механик', 'оператор'];
const LOCATIONS = {
  'мп': 'МП', 'тц': 'ТЦ', 'бц': 'БЦ', 'жк': 'ЖК',
  'мега': 'ТЦ Мега', 'ашан': 'Ашан', 'леруа': 'Леруа Мерлен',
  'икея': 'IKEA', 'ikea': 'IKEA', 'ozon': 'Ozon', 'озон': 'Ozon',
  'вб': 'Wildberries', 'wildberries': 'Wildberries'
};

const result = {
  full_name: existingData.full_name || null,
  age: existingData.age || null,
  gender: existingData.gender || null,
  position: existingData.position || null,
  experience: existingData.experience || null,
  phone: existingData.phone || null,
  object_location: existingData.object_location || null,
  candidates: [] // для множественных кандидатов
};

const lines = text.split('\n').map(l => l.trim()).filter(l => l);

// Regex patterns
const phoneRegex = /(?:\+7|8|7)[\s\-]?\(?\d{3}\)?[\s\-]?\d{3}[\s\-]?\d{2}[\s\-]?\d{2}/g;
const ageRegex = /(\d{1,2})\s*(лет|год|года)/i;
const expWithRegex = /с\s*опытом/i;
const expWithoutRegex = /без\s*опыта/i;
const nameRegex = /^[А-ЯЁа-яё][а-яё]+(?:\s+[А-ЯЁа-яё][а-яё]+){1,3}$/;

// Распознаём данные построчно
let currentCandidate = {};
let candidateLines = [];

for (const line of lines) {
  const lower = line.toLowerCase();

  // Телефон
  const phoneMatch = line.match(phoneRegex);
  if (phoneMatch) {
    const phone = phoneMatch[0].replace(/[^\d+]/g, '').replace(/^8/, '+7').replace(/^7(?!\+)/, '+7');
    if (currentCandidate.full_name) {
      currentCandidate.phone = phone;
      result.candidates.push({...currentCandidate});
      currentCandidate = {};
    } else {
      result.phone = phone;
    }
    continue;
  }

  // Возраст
  const ageMatch = line.match(ageRegex);
  if (ageMatch) {
    const age = parseInt(ageMatch[1]);
    if (age >= 16 && age <= 70) {
      if (currentCandidate.full_name) currentCandidate.age = age;
      else result.age = age;
    }
    continue;
  }

  // Опыт
  if (expWithRegex.test(lower)) {
    const exp = 'с опытом';
    if (currentCandidate.full_name) currentCandidate.experience = exp;
    else result.experience = exp;
    continue;
  }
  if (expWithoutRegex.test(lower)) {
    const exp = 'без опыта';
    if (currentCandidate.full_name) currentCandidate.experience = exp;
    else result.experience = exp;
    continue;
  }

  // Должность
  for (const pos of POSITIONS) {
    if (lower.includes(pos)) {
      result.position = line;
      break;
    }
  }

  // Локация
  for (const [key, val] of Object.entries(LOCATIONS)) {
    if (lower === key || lower.includes(key)) {
      result.object_location = val;
      break;
    }
  }

  // ФИО (кириллица, 2-4 слова)
  if (nameRegex.test(line) && !result.phone) {
    // Определяем пол по окончанию
    let gender = null;
    if (/[ая]$/i.test(line.split(' ')[0])) gender = 'ж';
    else if (/[ов]$/i.test(line.split(' ')[0])) gender = 'м';

    if (!result.full_name) {
      result.full_name = line;
      result.gender = gender;
    } else {
      // Это следующий кандидат
      if (currentCandidate.full_name) {
        result.candidates.push({...currentCandidate});
      }
      currentCandidate = { full_name: line, gender };
    }
  }
}

// Добавляем последнего кандидата если есть
if (currentCandidate.full_name && currentCandidate.phone) {
  result.candidates.push({...currentCandidate});
}

// Если нашли несколько кандидатов, используем первого как основного
if (result.candidates.length > 0 && !result.full_name) {
  const first = result.candidates[0];
  result.full_name = first.full_name;
  result.age = first.age || result.age;
  result.gender = first.gender || result.gender;
  result.phone = first.phone || result.phone;
  result.experience = first.experience || result.experience;
}

return {
  json: {
    ...input,
    parsedData: result,
    candidatesCount: result.candidates.length || 1
  }
};

// Process regex parser result
const input = $input.item.json;
const parsedData = input.parsedData;
const routeData = input;

// Merge existing and parsed data
const existingData = routeData.state?.collectedData || {};
const collectedData = {
  ...existingData,
  ...(parsedData.full_name && { full_name: parsedData.full_name }),
  ...(parsedData.age && { age: parsedData.age }),
  ...(parsedData.gender && { gender: parsedData.gender }),
  ...(parsedData.position && { position: parsedData.position }),
  ...(parsedData.experience && { experience: parsedData.experience }),
  ...(parsedData.phone && { phone: parsedData.phone }),
  ...(parsedData.object_location && { object_location: parsedData.object_location })
};

const requiredFields = ['full_name', 'phone', 'position', 'object_location'];
const missingFields = requiredFields.filter(f => !collectedData[f]);
const isComplete = missingFields.length === 0;

// Build clarification question based on missing fields
const labels = { full_name: 'ФИО', phone: 'телефон', position: 'должность', object_location: 'объект' };
let clarificationQuestion = null;
if (!isComplete) {
  clarificationQuestion = `Укажите: ${missingFields.map(f => labels[f]).join(', ')}`;
}

return {
  json: {
    ...routeData,
    collectedData,
    isComplete,
    missingFields,
    clarificationQuestion,
    candidatesCount: parsedData.candidates?.length || 1,
    additionalCandidates: parsedData.candidates?.slice(1) || []
  }
};

// Build response message with progress bar
const duplicates = $input.all().map(i => i.json).filter(d => d.id);
const processData = $('Process LLM').item.json;
const data = processData.collectedData;
const isComplete = processData.isComplete;
const missingFields = processData.missingFields;

// Check for high-match duplicates
const highMatch = duplicates.find(d => d.similarity_score >= 90);
if (highMatch) {
  return {
    json: {
      ...processData,
      responseType: 'duplicate',
      duplicate: highMatch,
      text: `⚠️ *Найден похожий кандидат* (${highMatch.similarity_score}%):\n\n👤 ${highMatch.full_name}\n📞 ${highMatch.phone}\n💼 ${highMatch.position}\n📍 ${highMatch.object_location}\n📊 ${highMatch.status}\n\nЧто сделать?`,
      keyboard: {
        inline_keyboard: [
          [{ text: '➕ Добавить новый', callback_data: `duplicate_add_${highMatch.id}` }, { text: '🔗 Обновить', callback_data: `duplicate_update_${highMatch.id}` }],
          [{ text: '❌ Отмена', callback_data: 'duplicate_cancel' }]
        ]
      }
    }
  };
}

const labels = { full_name: 'ФИО', phone: 'Телефон', position: 'Должность', object_location: 'Объект', age: 'Возраст', gender: 'Пол', experience: 'Опыт' };
const required = ['full_name', 'phone', 'position', 'object_location'];
const optional = ['age', 'gender', 'experience'];

let text = '📋 *Данные кандидата*\n\n*Обязательные:*\n';
let filled = 0;
required.forEach(f => {
  if (data[f]) { text += `✅ ${labels[f]}: ${data[f]}\n`; filled++; }
  else text += `❌ ${labels[f]}: _не указано_\n`;
});

text += '\n*Дополнительные:*\n';
optional.forEach(f => {
  if (data[f]) text += `✅ ${labels[f]}: ${data[f]}\n`;
  else text += `⬜ ${labels[f]}: _не указано_\n`;
});

const pct = Math.round((filled / required.length) * 100);
const bar = '█'.repeat(Math.round(pct/10)) + '░'.repeat(10 - Math.round(pct/10));
text += `\n📊 [${bar}] ${pct}%`;

let keyboard;
if (isComplete) {
  text += '\n\n✅ Все обязательные поля заполнены!';
  keyboard = { inline_keyboard: [[{ text: '✅ Сохранить', callback_data: 'confirm_yes' }, { text: '✏️ Изменить', callback_data: 'confirm_edit' }], [{ text: '❌ Отмена', callback_data: 'confirm_cancel' }]] };
} else {
  const q = processData.clarificationQuestion || `Укажите: ${missingFields.map(f => labels[f]).join(', ')}`;
  text += `\n\n${q}`;
  const btns = missingFields.slice(0,4).map(f => ({ text: `➕ ${labels[f]}`, callback_data: `add_field_${f}` }));
  keyboard = { inline_keyboard: [btns.slice(0,2), btns.slice(2,4), [{ text: '❌ Отмена', callback_data: 'confirm_cancel' }]].filter(r => r.length) };
}

return {
  json: {
    ...processData,
    responseType: isComplete ? 'confirm' : 'incomplete',
    text,
    keyboard
  }
};

// Parse payment message
const routeData = $input.item.json;
const text = routeData.message.text || '';
const lines = text.split('\n').map(l => l.trim()).filter(l => l);

const result = { workDate: null, objectLocation: null, position: null, employees: [], errors: [], isValid: false };

// Date (line 1)
const dateMatch = lines[0]?.match(/^(\d{1,2})\.(\d{1,2})(?:\.(\d{2,4}))?$/);
if (dateMatch) {
  const d = dateMatch[1].padStart(2,'0'), m = dateMatch[2].padStart(2,'0'), y = dateMatch[3] || new Date().getFullYear();
  result.workDate = `${y}-${m}-${d}`;
} else result.errors.push('Не распознана дата');

// Object (line 2)
if (lines[1]) result.objectLocation = lines[1];
else result.errors.push('Не указан объект');

// Position (line 3)
if (lines[2]) result.position = lines[2];
else result.errors.push('Не указана должность');

// Employees (remaining lines)
for (let i = 3; i < lines.length; i++) {
  const line = lines[i];
  let match = line.match(/^([А-Яа-яЁё\s\.]+)\s+(\d+(?:\.\d+)?)$/) ||
              line.match(/^(\d+(?:\.\d+)?)\s+([А-Яа-яЁё\s\.]+)$/)?.reverse() ||
              line.match(/^([А-Яа-яЁё\s\.]+)[\-:]\s*(\d+(?:\.\d+)?)$/);
  if (match) result.employees.push({ fullName: match[1].trim(), hours: parseFloat(match[2]) });
  else if (line.length > 2) result.errors.push(`Не распознано: ${line}`);
}

result.isValid = result.workDate && result.objectLocation && result.position && result.employees.length > 0;

return { json: { ...routeData, parsed: result } };

// Prepare batch records
const input = $input.item.json;
const p = input.parsed;
const m = input.message;

const records = p.employees.map(e => ({
  work_date: p.workDate,
  object_location: p.objectLocation,
  position: p.position,
  full_name: e.fullName,
  hours: e.hours,
  telegram_user_id: m.from.id,
  telegram_username: m.from.username,
  telegram_chat_id: m.chat.id,
  telegram_message_id: m.message_id
}));

return records.map(r => ({ json: r }));

// Build payment confirmation
const parseData = $('Parse Payment').item.json;
const p = parseData.parsed;

const date = new Date(p.workDate).toLocaleDateString('ru-RU', { day: 'numeric', month: 'long' });
let text = `✅ *Оплата записана*

📅 ${date}
📍 ${p.objectLocation}
💼 ${p.position}

👥 Сотрудников: ${p.employees.length}
⏱ Часов: ${p.employees.reduce((s,e) => s + e.hours, 0)}

`;
p.employees.forEach((e, i) => text += `${i+1}. ${e.fullName} — ${e.hours} ч.
`);

return { json: { text, chatId: parseData.chatId, messageId: parseData.message.message_id } };

// Build payment error
const input = $input.item.json;
const errors = input.parsed.errors;

let text = '❌ *Ошибка разбора*

';
if (errors.length) text += errors.map(e => `• ${e}`).join('
');
text += '

*Формат:*
```
26.01
МП
Горничная
Иванова Юлия 11
Петрова Мария 8
```';

return { json: { text, chatId: input.chatId, messageId: input.message.message_id } };
